"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["76826"],{28531(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.nome_obrigatorio","status":422,"titulo":"O nome da etapa \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.nome_obrigatorio","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["Uma das etapas do corpo do pedido de defini\xe7\xe3o de etapas n\xe3o tem `nome`, ou tem o\\ncampo vazio, ou s\xf3 com espa\xe7os em branco.","Esta confer\xeancia faz parte da confer\xeancia de **forma** das etapas: ela roda numa\\nprimeira passada que confere todas as etapas do corpo do pedido **antes** de resolver\\nqualquer uma contra o cat\xe1logo de tipos de etapa. Em cada etapa, a passada\\nconfere, nesta ordem:","- o `nome`: ausente ou em branco (este c\xf3digo) ou com mais de 300 caracteres\\n  ([`nome_tamanho`](/erros/uniplus.selecao.etapa_processo.nome_tamanho)); os dois\\n  s\xe3o mutuamente exclusivos, e a mesma etapa nunca aciona os dois;\\n- o `carater`: ausente ou fora das op\xe7\xf5es\\n  ([`carater_obrigatorio`](/erros/uniplus.selecao.etapa_processo.carater_obrigatorio));\\n- o `peso`: menor ou igual a zero\\n  ([`peso_invalido`](/erros/uniplus.selecao.etapa_processo.peso_invalido)) ou\\n  informado em etapa apenas eliminat\xf3ria\\n  (`uniplus.selecao.etapa_processo.peso_sem_carater_que_pontua`);\\n- a `notaMinima`: negativa\\n  ([`nota_minima_invalida`](/erros/uniplus.selecao.etapa_processo.nota_minima_invalida))\\n  ou informada em etapa apenas classificat\xf3ria\\n  (`uniplus.selecao.etapa_processo.nota_minima_sem_carater_que_elimina`);\\n- a escala da nota: `notaMaxima` menor ou igual a zero\\n  ([`nota_maxima_invalida`](/erros/uniplus.selecao.etapa_processo.nota_maxima_invalida)),\\n  `passoDoLancamento` menor ou igual a zero\\n  ([`passo_do_lancamento_invalido`](/erros/uniplus.selecao.etapa_processo.passo_do_lancamento_invalido)),\\n  nota m\xednima acima da m\xe1xima\\n  ([`nota_minima_acima_da_nota_maxima`](/erros/uniplus.selecao.etapa_processo.nota_minima_acima_da_nota_maxima))\\n  e nota m\xe1xima que n\xe3o \xe9 m\xfaltipla do passo\\n  ([`nota_maxima_fora_do_passo`](/erros/uniplus.selecao.etapa_processo.nota_maxima_fora_do_passo));\\n- a `ordem`: ausente ou menor ou igual a zero\\n  ([`ordem_invalida`](/erros/uniplus.selecao.etapa_processo.ordem_invalida));\\n- os itens de avalia\xe7\xe3o da etapa (r\xf3tulo inv\xe1lido ou repetido, `id` repetido,\\n  pontua\xe7\xe3o m\xe1xima inv\xe1lida ou fora do passo), com os c\xf3digos\\n  `uniplus.selecao.item_de_avaliacao.*`;\\n- a escala de atendimento da etapa (r\xf3tulo inv\xe1lido ou repetido, fra\xe7\xe3o fora de\\n  0 a 1, aus\xeancia de um n\xedvel de fra\xe7\xe3o 1), com os c\xf3digos\\n  `uniplus.selecao.nivel_de_atendimento.*`.","A passada acumula toda viola\xe7\xe3o de forma encontrada, de todas as etapas, em vez\\nde recusar na primeira: um corpo do pedido com uma etapa sem nome e outra com peso\\nnegativo devolve as duas viola\xe7\xf5es juntas, no array `errors[]` do corpo de\\nerro \u2014 cada item com seu `field` (`etapas[<\xedndice>].nome`, por exemplo) e seu\\npr\xf3prio `code`. O `type`/`title` da raiz do corpo de erro refletem a\\n**primeira** viola\xe7\xe3o encontrada: entre etapas, a ordem do array do corpo do pedido;\\ndentro de uma etapa, a ordem da lista acima."],"comoResolver":["Preencha o campo `nome` de cada etapa do corpo do pedido com um texto n\xe3o vazio. Um\\nvalor s\xf3 com espa\xe7os em branco \xe9 tratado como ausente.","Se a resposta trouxer mais de uma viola\xe7\xe3o no array `errors[]`, corrija todas\\nantes de reenviar \u2014 a passada de forma s\xf3 libera a etapa para seguir \xe0\\nresolu\xe7\xe3o do tipo de etapa quando **nenhuma** etapa do corpo do pedido tem viola\xe7\xe3o de\\nforma pendente."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);